" + "  public <T extends Comparable<T>> IncrementallyUpdatedFilterPredicate visit("
        + inVar + "<T> pred) {
" + "    ColumnPath columnPath = pred.getColumn().getColumnPath();
"
        + "    Class<T> clazz = pred.getColumn().getColumnType();
"
        + "
"
        + "    ValueInspector valueInspector = null;

");
