package org.apache.parquet.filter2;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

public class IncrementallyUpdatedFilterPredicateGeneratorRunTests {

  @Test
  void runGeneratesBuilderSourceWithRequiredPredicateVisitors() throws Exception {
    Path output = Files.createTempFile("incrementally-updated-filter-predicate-builder", ".java");

    try {
      IncrementallyUpdatedFilterPredicateGenerator generator =
          new IncrementallyUpdatedFilterPredicateGenerator(output.toFile());

      generator.run();

      String generated = Files.readString(output, StandardCharsets.UTF_8);

      assertTrue(generated.contains("package org.apache.parquet.filter2.recordlevel;"));
      assertTrue(generated.contains(
          "public class IncrementallyUpdatedFilterPredicateBuilder "
              + "extends IncrementallyUpdatedFilterPredicateBuilderBase"));
      assertTrue(generated.contains(
          "public IncrementallyUpdatedFilterPredicateBuilder(List<PrimitiveColumnIO> leaves)"));
      assertTrue(generated.contains("visit(Eq"));
      assertTrue(generated.contains("visit(NotEq"));
      assertTrue(generated.contains("visit(In"));
      assertTrue(generated.contains("visit(NotIn"));
      assertTrue(generated.contains("visit(Contains"));
      assertTrue(generated.contains("visit(Lt"));
      assertTrue(generated.contains("visit(LtEq"));
      assertTrue(generated.contains("visit(Gt"));
      assertTrue(generated.contains("visit(GtEq"));
      assertTrue(generated.contains("visit(UserDefined"));
      assertTrue(generated.contains("visit(LogicalNotUserDefined"));
      assertTrue(generated.contains("import org.apache.parquet.filter2.predicate.Operators;"));
      assertTrue(generated.contains(
          "import org.apache.parquet.filter2.recordlevel.IncrementallyUpdatedFilterPredicate.ValueInspector;"));
    } finally {
      Files.deleteIfExists(output);
    }
  }

  @Test
  void runProducesAClosedReadableGeneratedFile() throws Exception {
    Path output = Files.createTempFile("incrementally-updated-filter-predicate-builder", ".java");

    try {
      IncrementallyUpdatedFilterPredicateGenerator generator =
          new IncrementallyUpdatedFilterPredicateGenerator(output.toFile());

      generator.run();

      String generated = Files.readString(output, StandardCharsets.UTF_8);

      assertTrue(generated.length() > 1000);
      assertTrue(generated.endsWith("}\n") || generated.endsWith("}"));
      assertTrue(Files.size(output) > 0);
    } finally {
      Files.deleteIfExists(output);
    }
  }
}

package org.apache.parquet.filter2;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.assertThrows;
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import org.junit.jupiter.api.io.TempDir;

class IncrementallyUpdatedFilterPredicateGeneratorRunTests {

    @TempDir
    File tempDir;

    @Test
    void testRunGeneratesExpectedClassStructure() throws IOException {
        File outputFile = new File(tempDir, "GeneratedBuilder.java");
        IncrementallyUpdatedFilterPredicateGenerator generator = new IncrementallyUpdatedFilterPredicateGenerator(outputFile);

        generator.run();

        String content = Files.readString(outputFile.toPath());

        assertTrue(content.contains("package org.apache.parquet.filter2.recordlevel;"), "Should contain correct package declaration");
        assertTrue(content.contains("public class IncrementallyUpdatedFilterPredicateBuilder extends IncrementallyUpdatedFilterPredicateBuilderBase"), "Should define the target class");
        assertTrue(content.contains("public IncrementallyUpdatedFilterPredicateBuilder(List<PrimitiveColumnIO> leaves)"), "Should contain constructor");
        assertTrue(content.contains("super(leaves);"), "Constructor should call super");
        assertTrue(content.contains("visit(Eq"), "Should handle Eq predicate");
        assertTrue(content.contains("visit(NotEq"), "Should handle NotEq predicate");
        assertTrue(content.contains("visit(In"), "Should handle In predicate");
        assertTrue(content.contains("visit(NotIn"), "Should handle NotIn predicate");
        assertTrue(content.contains("visit(Contains"), "Should handle Contains predicate");
        assertTrue(content.contains("visit(Lt"), "Should handle Lt predicate");
        assertTrue(content.contains("visit(LtEq"), "Should handle LtEq predicate");
        assertTrue(content.contains("visit(Gt"), "Should handle Gt predicate");
        assertTrue(content.contains("visit(GtEq"), "Should handle GtEq predicate");
        assertTrue(content.contains("visit(UserDefined"), "Should handle UserDefined predicate");
        assertTrue(content.contains("visit(LogicalNotUserDefined"), "Should handle LogicalNotUserDefined predicate");
        assertTrue(content.contains("@Override"), "Methods should be annotated as overrides");
    }

    @Test
    void testConstructorThrowsIOExceptionForInvalidPath() {
        File invalidFile = new File("/nonexistent/directory/that/does/not/exist/output.java");
        assertThrows(IOException.class, () -> new IncrementallyUpdatedFilterPredicateGenerator(invalidFile));
    }
}
